import 'package:flutter/material.dart';
class ResultPage extends StatelessWidget{final int score,totalQuestions,attempted;const ResultPage({super.key,required this.score,required this.totalQuestions,required this.attempted});@override Widget build(BuildContext context){final skipped=totalQuestions-attempted;final incorrect=attempted-score;final pct=totalQuestions==0?0:(score/totalQuestions*100);Widget card(String t,String v,Color c)=>Card(child:ListTile(title:Text(t),trailing:Text(v,style:TextStyle(fontWeight:FontWeight.bold,color:c))));return Scaffold(appBar:AppBar(title:const Text("Quiz Result")),body:Padding(padding:const EdgeInsets.all(16),child:Column(children:[const Icon(Icons.emoji_events,size:90,color:Colors.amber),Text("${pct.toStringAsFixed(1)}%",style:const TextStyle(fontSize:34,fontWeight:FontWeight.bold)),const SizedBox(height:20),card("Correct","$score",Colors.green),card("Incorrect","$incorrect",Colors.red),card("Attempted","$attempted",Colors.blue),card("Skipped","$skipped",Colors.orange),const Spacer(),SizedBox(width:double.infinity,child:FilledButton(onPressed:()=>Navigator.popUntil(context,(r)=>r.isFirst),child:const Text("Back to Home")))])));} }